   315	function initMoneyRequest(reportID: string, policy: OnyxEntry<OnyxTypes.Policy>, isFromGlobalCreate: boolean, iouRequestType: IOURequestType = CONST.IOU.REQUEST_TYPE.MANUAL) {
   316	    // Generate a brand new transactionID
   317	    const newTransactionID = CONST.IOU.OPTIMISTIC_TRANSACTION_ID;
   318	    const currency = policy?.outputCurrency ?? currentUserPersonalDetails?.localCurrencyCode ?? CONST.CURRENCY.USD;
   319	    // Disabling this line since currentDate can be an empty string
   320	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   321	    const created = currentDate || format(new Date(), 'yyyy-MM-dd');
   322	
   323	    const currentTransaction = allTransactionDrafts?.[`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`];
   324	
   325	    // in case we have to re-init money request, but the IOU request type is the same with the old draft transaction,
   326	    // we should keep most of the existing data by using the ONYX MERGE operation
   327	    if (currentTransaction?.iouRequestType === iouRequestType) {
   328	        // so, we just need to update the reportID, isFromGlobalCreate, created, currency
   329	        Onyx.merge(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   330	            reportID,
   331	            isFromGlobalCreate,
   332	            created,
   333	            currency,
   334	            transactionID: newTransactionID,
   335	        });
   336	        return;
   337	    }
   338	
   339	    const comment: Comment = {};
   340	
   341	    // Add initial empty waypoints when starting a distance expense
   342	    if (iouRequestType === CONST.IOU.REQUEST_TYPE.DISTANCE) {
   343	        comment.waypoints = {
   344	            waypoint0: {keyForList: 'start_waypoint'},
   345	            waypoint1: {keyForList: 'stop_waypoint'},
   346	        };
   347	        if (!isFromGlobalCreate) {
   348	            const customUnitRateID = DistanceRequestUtils.getCustomUnitRateID(reportID);
   349	            comment.customUnit = {customUnitRateID};
   350	        }
   351	    }
   352	
   353	    // Store the transaction in Onyx and mark it as not saved so it can be cleaned up later
   354	    // Use set() here so that there is no way that data will be leaked between objects when it gets reset
   355	    Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   356	        amount: 0,
   357	        comment,
   358	        created,
   359	        currency,
   360	        iouRequestType,
   361	        reportID,
   362	        transactionID: newTransactionID,
   363	        isFromGlobalCreate,
   364	        merchant: CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   365	        splitPayerAccountIDs: currentUserPersonalDetails ? [currentUserPersonalDetails.accountID] : undefined,
   366	    });
   367	}
